```js
import { reactive, watch } from 'vue'
import { api } from '../api/client'
import { useAuth } from './useAuth'

const state = reactive({ channels: [] })
const { state: auth } = useAuth()

async function reload() {
  try {
    state.channels = await api.subscriptions.list()
  } catch {
    /* список в сайдбаре не критичен */
  }
}

// Watcher на уровне модуля, а не компонента: он не должен умирать вместе с компонентом
watch(
  () => auth.user?.id,
  (id) => {
    if (id) reload()
    else state.channels = []
  },
  { immediate: true },
)

export function useSubscriptions() {
  return { state, reload }
}
```

В `frontend/src/components/SubscribeButton.vue` добавь импорт `import { useSubscriptions } from '../composables/useSubscriptions'`, строку `const { reload: reloadSubscriptions } = useSubscriptions()` рядом с `const { state: auth } = useAuth()` и вызов после `emit('changed', res)`:

```js
