## Шаг 5. Страница просмотра

`frontend/src/composables/clipboard.js`:

```js
// navigator.clipboard работает только в безопасном контексте (HTTPS или localhost).
// На сервере по http://<ip>/ его нет, поэтому есть запасной путь через execCommand.
export async function copyText(text) {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text)
      return true
    }
  } catch {
    /* падаем на запасной способ */
  }
  const area = document.createElement('textarea')
  area.value = text
  area.setAttribute('readonly', '')
  area.style.cssText = 'position:fixed;top:0;left:0;opacity:0'
  document.body.appendChild(area)
  area.select()
  let ok = false
  try {
    ok = document.execCommand('copy')
  } catch {
    ok = false
  }
  area.remove()
  return ok
}
```

