    default "";
}
map $request_method $write_key {
    POST    $binary_remote_addr;
    PUT     $binary_remote_addr;
    PATCH   $binary_remote_addr;
    DELETE  $binary_remote_addr;
    default "";
}
map $request_method $view_key {
    POST    "$binary_remote_addr$uri";   # по одному видео, а не по всем сразу
    default "";
}

limit_req_zone $binary_remote_addr zone=api:5m      rate=30r/s;
limit_req_zone $write_key          zone=writes:5m   rate=60r/m;
limit_req_zone $binary_remote_addr zone=auth:5m     rate=10r/m;
limit_req_zone $post_key           zone=create:5m   rate=10r/m;
limit_req_zone $binary_remote_addr zone=upload:5m   rate=6r/m;
limit_req_zone $post_key           zone=comments:5m rate=20r/m;
limit_req_zone $post_key           zone=reports:5m  rate=10r/m;
limit_req_zone $view_key           zone=views:5m    rate=6r/m;

server {
    listen 80;
    server_name _;
    server_tokens off;

    # Docker DNS: резолвим api на каждый запрос, иначе после пересборки api будет 502 на старый IP
    resolver 127.0.0.11 valid=10s ipv6=off;
    set $api_upstream http://api:8000;

    root /usr/share/nginx/html;
    index index.html;

    # По умолчанию маленький лимит, большой только на загрузке файла
